// Persist to database via bulkCreate
await Instrument.bulkCreate(instruments, {
  updateOnDuplicate: ['name', 'type', 'category'],
});
console.log(`✅ 成功持久化 ${instruments.length} 个标的到数据库`);

// Backup to filesystem
try {
  const fs = require('fs');
  const path = require('path');
  const dataDir = path.join(__dirname, '../../data');

  if (!fs.existsSync(dataDir)) {
    fs.mkdirSync(dataDir, { recursive: true });
  }

  const filePath = path.join(dataDir, 'instruments.json');
  fs.writeFileSync(filePath, JSON.stringify({
    data: instruments,
    timestamp: Date.now(),
    count: instruments.length
  }, null, 2));
  console.log(`📁 文件备份已写入: ${filePath}`);
} catch (fsError) {
  console.warn('⚠️ 文件备份写入失败 (不影响主流程):', fsError.message);
}
